-- ملاحظات مهمة لأداء كل تمرين في المكتبة (تُضاف لتعليمات الأداء التي يراها المتدرب). بيانات فقط، آمنة للتكرار.
-- عامة بحسب نمط الحركة والمعدات. التمارين التأهيلية مستثناة (لها ملاحظات سلامتها).
BEGIN;
UPDATE exercises e
   SET instructions = CASE WHEN coalesce(trim(e.instructions), '') = '' THEN x.notes ELSE e.instructions || E'\n\n' || x.notes END
  FROM jsonb_to_recordset($nt$[{"name":"Back Squat","notes":"ملاحظات مهمة:\n• ركبتان بنفس اتجاه أصابع القدم وثبات الكعبين على الأرض.\n• صدر مرفوع وجذع محايد، وانزل بعمق يسمح به مدى حركتك دون ثني أسفل الظهر.\n• ادفع الأرض بكامل القدم وليس بالأصابع فقط.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Box Squat","notes":"ملاحظات مهمة:\n• ركبتان بنفس اتجاه أصابع القدم وثبات الكعبين على الأرض.\n• صدر مرفوع وجذع محايد، وانزل بعمق يسمح به مدى حركتك دون ثني أسفل الظهر.\n• ادفع الأرض بكامل القدم وليس بالأصابع فقط.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Hack Squat","notes":"ملاحظات مهمة:\n• ثبّت ظهرك على المسند وضع القدمين بوضع مريح للركبة.\n• انزل بتحكم وادفع بالكعبين وكامل القدم دون تقوّس الظهر.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Mid Leg Press","notes":"ملاحظات مهمة:\n• لا ترفع الأرداف عن المقعد ولا تفرد الركبتين بقوة في الأعلى.\n• ضع القدمين بحيث تبقى الركبتان باتجاه أصابع القدم، وانزل لمدى يسمح بأسفل ظهر ملتصق بالمسند.\n• تحكم في النزول 2–3 ثوانٍ.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Quads Leg Press","notes":"ملاحظات مهمة:\n• لا ترفع الأرداف عن المقعد ولا تفرد الركبتين بقوة في الأعلى.\n• ضع القدمين بحيث تبقى الركبتان باتجاه أصابع القدم، وانزل لمدى يسمح بأسفل ظهر ملتصق بالمسند.\n• تحكم في النزول 2–3 ثوانٍ.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Deficit Goblet Squat","notes":"ملاحظات مهمة:\n• ركبتان بنفس اتجاه أصابع القدم وثبات الكعبين على الأرض.\n• صدر مرفوع وجذع محايد، وانزل بعمق يسمح به مدى حركتك دون ثني أسفل الظهر.\n• ادفع الأرض بكامل القدم وليس بالأصابع فقط.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Front Squat","notes":"ملاحظات مهمة:\n• ركبتان بنفس اتجاه أصابع القدم وثبات الكعبين على الأرض.\n• صدر مرفوع وجذع محايد، وانزل بعمق يسمح به مدى حركتك دون ثني أسفل الظهر.\n• ادفع الأرض بكامل القدم وليس بالأصابع فقط.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"V Squat","notes":"ملاحظات مهمة:\n• ثبّت ظهرك على المسند وضع القدمين بوضع مريح للركبة.\n• انزل بتحكم وادفع بالكعبين وكامل القدم دون تقوّس الظهر.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Resistance Band Squat","notes":"ملاحظات مهمة:\n• ركبتان بنفس اتجاه أصابع القدم وثبات الكعبين على الأرض.\n• صدر مرفوع وجذع محايد، وانزل بعمق يسمح به مدى حركتك دون ثني أسفل الظهر.\n• ادفع الأرض بكامل القدم وليس بالأصابع فقط.\n• تأكد من سلامة الشريط وثبّته جيداً، واحرص على شد ثابت طوال الحركة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Squat Smith Machine","notes":"ملاحظات مهمة:\n• ثبّت ظهرك على المسند وضع القدمين بوضع مريح للركبة.\n• انزل بتحكم وادفع بالكعبين وكامل القدم دون تقوّس الظهر.\n• ضع القدمين بزاوية مناسبة وأمامية قليلاً، واضبط حوامل الأمان قبل البدء.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Single Leg Press","notes":"ملاحظات مهمة:\n• لا تفرد الركبة بقوة في الأعلى، وحافظ على الحوض ثابتاً على المقعد.\n• انزل بتحكم بدون أن ترتفع الأرداف.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Drop Lunges","notes":"ملاحظات مهمة:\n• خطوة طويلة بما يكفي ليبقى الساق الأمامي بزاوية نحو 90° والركبة فوق القدم.\n• جذع مستقيم وشدّ البطن، وادفع بكعب الرجل الأمامية.\n• تحكم في التوازن قبل زيادة الوزن.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Beginner Lunges","notes":"ملاحظات مهمة:\n• خطوة طويلة بما يكفي ليبقى الساق الأمامي بزاوية نحو 90° والركبة فوق القدم.\n• جذع مستقيم وشدّ البطن، وادفع بكعب الرجل الأمامية.\n• تحكم في التوازن قبل زيادة الوزن.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Supported BSS","notes":"ملاحظات مهمة:\n• وضعية ثابتة بوقفة طويلة، وانزل عمودياً لا للأمام.\n• ادفع بكعب الرجل الأمامية وحافظ على الحوض مستوياً.\n• ثبّت قبل التكرار الأول لضمان التوازن.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Supported Reverse Lunge","notes":"ملاحظات مهمة:\n• خطوة طويلة بما يكفي ليبقى الساق الأمامي بزاوية نحو 90° والركبة فوق القدم.\n• جذع مستقيم وشدّ البطن، وادفع بكعب الرجل الأمامية.\n• تحكم في التوازن قبل زيادة الوزن.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Smith Machine Reverse Lunge","notes":"ملاحظات مهمة:\n• خطوة طويلة بما يكفي ليبقى الساق الأمامي بزاوية نحو 90° والركبة فوق القدم.\n• جذع مستقيم وشدّ البطن، وادفع بكعب الرجل الأمامية.\n• تحكم في التوازن قبل زيادة الوزن.\n• ضع القدمين بزاوية مناسبة وأمامية قليلاً، واضبط حوامل الأمان قبل البدء.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Leg Extension","notes":"ملاحظات مهمة:\n• اضبط مسند الظهر بحيث تكون الركبة مقابلة لمحور الجهاز.\n• افرد الركبة بتحكم دون قذف الوزن، وانقباض لثانية في الأعلى.\n• تجنّب الأوزان الثقيلة جداً إذا شعرت بألم في الركبة.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Single Leg Extension","notes":"ملاحظات مهمة:\n• اضبط مسند الظهر بحيث تكون الركبة مقابلة لمحور الجهاز.\n• افرد الركبة بتحكم دون قذف الوزن، وانقباض لثانية في الأعلى.\n• تجنّب الأوزان الثقيلة جداً إذا شعرت بألم في الركبة.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Band Leg Extension","notes":"ملاحظات مهمة:\n• اضبط مسند الظهر بحيث تكون الركبة مقابلة لمحور الجهاز.\n• افرد الركبة بتحكم دون قذف الوزن، وانقباض لثانية في الأعلى.\n• تجنّب الأوزان الثقيلة جداً إذا شعرت بألم في الركبة.\n• تأكد من سلامة الشريط وثبّته جيداً، واحرص على شد ثابت طوال الحركة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Sissy Squat","notes":"ملاحظات مهمة:\n• حركة متقدمة: ابدأ بمدى قصير بمساندة ثم زد المدى.\n• حافظ على خط مستقيم من الركبة إلى الكتف.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Cable Leg Extension","notes":"ملاحظات مهمة:\n• اضبط مسند الظهر بحيث تكون الركبة مقابلة لمحور الجهاز.\n• افرد الركبة بتحكم دون قذف الوزن، وانقباض لثانية في الأعلى.\n• تجنّب الأوزان الثقيلة جداً إذا شعرت بألم في الركبة.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Standing Leg Extension","notes":"ملاحظات مهمة:\n• اضبط مسند الظهر بحيث تكون الركبة مقابلة لمحور الجهاز.\n• افرد الركبة بتحكم دون قذف الوزن، وانقباض لثانية في الأعلى.\n• تجنّب الأوزان الثقيلة جداً إذا شعرت بألم في الركبة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Bodyweight Squat","notes":"ملاحظات مهمة:\n• ركبتان بنفس اتجاه أصابع القدم وثبات الكعبين على الأرض.\n• صدر مرفوع وجذع محايد، وانزل بعمق يسمح به مدى حركتك دون ثني أسفل الظهر.\n• ادفع الأرض بكامل القدم وليس بالأصابع فقط.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"DB Glutes Step Ups","notes":"ملاحظات مهمة:\n• اصعد بقوة الرجل التي على الدرجة لا بدفع الرجل الخلفية.\n• اختر ارتفاعاً بحيث تكون الركبة نحو 90° أو أقل، وانزل بتحكم.\n• جذع مرفوع وحوض مستوٍ.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Supported Glutes Step Ups","notes":"ملاحظات مهمة:\n• اصعد بقوة الرجل التي على الدرجة لا بدفع الرجل الخلفية.\n• اختر ارتفاعاً بحيث تكون الركبة نحو 90° أو أقل، وانزل بتحكم.\n• جذع مرفوع وحوض مستوٍ.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Cable Glutes Step Ups","notes":"ملاحظات مهمة:\n• اصعد بقوة الرجل التي على الدرجة لا بدفع الرجل الخلفية.\n• اختر ارتفاعاً بحيث تكون الركبة نحو 90° أو أقل، وانزل بتحكم.\n• جذع مرفوع وحوض مستوٍ.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Glute Pushdown","notes":"ملاحظات مهمة:\n• اصعد بقوة الرجل التي على الدرجة لا بدفع الرجل الخلفية.\n• اختر ارتفاعاً بحيث تكون الركبة نحو 90° أو أقل، وانزل بتحكم.\n• جذع مرفوع وحوض مستوٍ.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Glute Max Kickbacks","notes":"ملاحظات مهمة:\n• حرّك الرجل من الورك دون تقوّس أسفل الظهر.\n• انقباض الألوية في نهاية الحركة، ونزول بطيء.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Smith Machine Kickback","notes":"ملاحظات مهمة:\n• حرّك الرجل من الورك دون تقوّس أسفل الظهر.\n• انقباض الألوية في نهاية الحركة، ونزول بطيء.\n• ضع القدمين بزاوية مناسبة وأمامية قليلاً، واضبط حوامل الأمان قبل البدء.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Glute Medius Kickbacks","notes":"ملاحظات مهمة:\n• ارفع الرجل للخلف وللخارج دون دوران الحوض.\n• وزن خفيف وانقباض واضح للألوية.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Hip Thrusts Machine","notes":"ملاحظات مهمة:\n• ذقن للأسفل قليلاً وضلوع للأسفل، ولا تبالغ في تقوّس أسفل الظهر في الأعلى.\n• ادفع بالكعبين، وانقباض الألوية في الأعلى لثانية.\n• ركبتان بزاوية نحو 90° في أعلى الحركة.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Hip Thrusts","notes":"ملاحظات مهمة:\n• ذقن للأسفل قليلاً وضلوع للأسفل، ولا تبالغ في تقوّس أسفل الظهر في الأعلى.\n• ادفع بالكعبين، وانقباض الألوية في الأعلى لثانية.\n• ركبتان بزاوية نحو 90° في أعلى الحركة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Glute Raise","notes":"ملاحظات مهمة:\n• الحركة من الورك لا من أسفل الظهر، وتوقف حين يستقيم الجسم دون تقوّس.\n• اضبط المسند بحيث يكون الورك حراً للانثناء.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Single Hip Thrusts","notes":"ملاحظات مهمة:\n• ذقن للأسفل قليلاً وضلوع للأسفل، ولا تبالغ في تقوّس أسفل الظهر في الأعلى.\n• ادفع بالكعبين، وانقباض الألوية في الأعلى لثانية.\n• ركبتان بزاوية نحو 90° في أعلى الحركة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Glute Press","notes":"ملاحظات مهمة:\n• حرّك الرجل من الورك دون تقوّس أسفل الظهر.\n• انقباض الألوية في نهاية الحركة، ونزول بطيء.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Bulgarian Split Squat","notes":"ملاحظات مهمة:\n• وضعية ثابتة بوقفة طويلة، وانزل عمودياً لا للأمام.\n• ادفع بكعب الرجل الأمامية وحافظ على الحوض مستوياً.\n• ثبّت قبل التكرار الأول لضمان التوازن.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Sumo Deadlift","notes":"ملاحظات مهمة:\n• ثبّت الظهر محايداً قبل الرفع وشدّ البطن (Brace) ثم ادفع الأرض بالقدمين.\n• ابقِ البار قريباً من الجسم طوال الحركة.\n• لا تقوّس أسفل الظهر عند أي مرحلة، ولا تفرد الركبتين قبل الورك.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Conventional Deadlift","notes":"ملاحظات مهمة:\n• ثبّت الظهر محايداً قبل الرفع وشدّ البطن (Brace) ثم ادفع الأرض بالقدمين.\n• ابقِ البار قريباً من الجسم طوال الحركة.\n• لا تقوّس أسفل الظهر عند أي مرحلة، ولا تفرد الركبتين قبل الورك.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"BB RDL","notes":"ملاحظات مهمة:\n• ادفع الورك للخلف مع ثني بسيط ثابت في الركبتين، والبار قريب من الساقين.\n• انزل حتى تمدد في الخلفية دون تقوّس الظهر، ثم ادفع الورك للأمام.\n• الحركة من الورك وليست انحناء بالظهر.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"DB RDL","notes":"ملاحظات مهمة:\n• ادفع الورك للخلف مع ثني بسيط ثابت في الركبتين، والبار قريب من الساقين.\n• انزل حتى تمدد في الخلفية دون تقوّس الظهر، ثم ادفع الورك للأمام.\n• الحركة من الورك وليست انحناء بالظهر.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"SM SLDL","notes":"ملاحظات مهمة:\n• ادفع الورك للخلف مع ثني بسيط ثابت في الركبتين، والبار قريب من الساقين.\n• انزل حتى تمدد في الخلفية دون تقوّس الظهر، ثم ادفع الورك للأمام.\n• الحركة من الورك وليست انحناء بالظهر.\n• ضع القدمين بزاوية مناسبة وأمامية قليلاً، واضبط حوامل الأمان قبل البدء.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"SLDL","notes":"ملاحظات مهمة:\n• ادفع الورك للخلف مع ثني بسيط ثابت في الركبتين، والبار قريب من الساقين.\n• انزل حتى تمدد في الخلفية دون تقوّس الظهر، ثم ادفع الورك للأمام.\n• الحركة من الورك وليست انحناء بالظهر.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Single DB SLDL","notes":"ملاحظات مهمة:\n• ادفع الورك للخلف مع ثني بسيط ثابت في الركبتين، والبار قريب من الساقين.\n• انزل حتى تمدد في الخلفية دون تقوّس الظهر، ثم ادفع الورك للأمام.\n• الحركة من الورك وليست انحناء بالظهر.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Good Morning","notes":"ملاحظات مهمة:\n• بار ثابت على أعلى الظهر، ودفع الورك للخلف مع ظهر محايد.\n• ابدأ بوزن خفيف جداً لإتقان الحركة.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Seated Leg Curl","notes":"ملاحظات مهمة:\n• اضبط الجهاز ليتماشى محور الركبة مع محور الجهاز.\n• اسحب بتحكم وبدون رفع الورك عن المقعد، وانزل ببطء.\n• انقباض لثانية في أقصى الثني.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Band Leg Curl","notes":"ملاحظات مهمة:\n• اضبط الجهاز ليتماشى محور الركبة مع محور الجهاز.\n• اسحب بتحكم وبدون رفع الورك عن المقعد، وانزل ببطء.\n• انقباض لثانية في أقصى الثني.\n• تأكد من سلامة الشريط وثبّته جيداً، واحرص على شد ثابت طوال الحركة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Lying Leg Curl","notes":"ملاحظات مهمة:\n• اضبط الجهاز ليتماشى محور الركبة مع محور الجهاز.\n• اسحب بتحكم وبدون رفع الورك عن المقعد، وانزل ببطء.\n• انقباض لثانية في أقصى الثني.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"DB Lying Leg Curl","notes":"ملاحظات مهمة:\n• اضبط الجهاز ليتماشى محور الركبة مع محور الجهاز.\n• اسحب بتحكم وبدون رفع الورك عن المقعد، وانزل ببطء.\n• انقباض لثانية في أقصى الثني.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Standing Leg Curl","notes":"ملاحظات مهمة:\n• اضبط الجهاز ليتماشى محور الركبة مع محور الجهاز.\n• اسحب بتحكم وبدون رفع الورك عن المقعد، وانزل ببطء.\n• انقباض لثانية في أقصى الثني.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Cable Leg Curl","notes":"ملاحظات مهمة:\n• اضبط الجهاز ليتماشى محور الركبة مع محور الجهاز.\n• اسحب بتحكم وبدون رفع الورك عن المقعد، وانزل ببطء.\n• انقباض لثانية في أقصى الثني.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Supine Cable Hamstring Curl","notes":"ملاحظات مهمة:\n• اضبط الجهاز ليتماشى محور الركبة مع محور الجهاز.\n• اسحب بتحكم وبدون رفع الورك عن المقعد، وانزل ببطء.\n• انقباض لثانية في أقصى الثني.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Nordic Hamstring Curl","notes":"ملاحظات مهمة:\n• ثبّت الكعبين جيداً وانزل ببطء قدر الإمكان بجسم مستقيم من الركبة للرأس.\n• استخدم اليدين لتخفيف الحمل في البداية، وتقدّم تدريجياً لتجنب شد الخلفية.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Stability Ball Hamstring Curl","notes":"ملاحظات مهمة:\n• ارفع الورك ثم اسحب الكعبين نحو الأرداف بتحكم.\n• لا تقوّس أسفل الظهر، ونزول بطيء.\n• ثبّت الكرة جيداً قبل البدء، وتحرك ببطء لتجنب الانزلاق.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Hip Hinge","notes":"ملاحظات مهمة:\n• تعلّم الحركة بوزن خفيف: ورك للخلف وظهر محايد.\n• العصا على الظهر تساعدك على مراقبة الاستقامة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"TRX Hamstrings Curl","notes":"ملاحظات مهمة:\n• ارفع الورك ثم اسحب الكعبين نحو الأرداف بتحكم.\n• لا تقوّس أسفل الظهر، ونزول بطيء.\n• تأكد من تثبيت الأحزمة جيداً، وحافظ على جسم مستقيم وتحكم في زاوية الميل لضبط الصعوبة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Flat DB Chest Press","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"DB Floor Chest Press","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Flat Bench Press","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Machine Chest Press","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Feet Up Bench Press","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Torso Elevated Push Up","notes":"ملاحظات مهمة:\n• ثبّت جسمك جيداً قبل البدء وانزل بتحكم إلى أسفل الصدر.\n• حافظ على الرسغ مستقيماً فوق الساعد.\n• استخدم مساعداً أو جهاز أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Push Up","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Bench Press","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Paused Bench Press","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Incline Press","notes":"ملاحظات مهمة:\n• اضبط الميل بزاوية معتدلة (نحو 30°) ليبقى التركيز على أعلى الصدر دون أن يطغى الكتف.\n• ثبّت لوحي الكتف للخلف وانزل بتحكم.\n• لا ترفع الأرداف عن المقعد.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Smith Machine Incline Press","notes":"ملاحظات مهمة:\n• اضبط الميل بزاوية معتدلة (نحو 30°) ليبقى التركيز على أعلى الصدر دون أن يطغى الكتف.\n• ثبّت لوحي الكتف للخلف وانزل بتحكم.\n• لا ترفع الأرداف عن المقعد.\n• ضع القدمين بزاوية مناسبة وأمامية قليلاً، واضبط حوامل الأمان قبل البدء.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Cable Chest Press","notes":"ملاحظات مهمة:\n• اضبط الميل بزاوية معتدلة (نحو 30°) ليبقى التركيز على أعلى الصدر دون أن يطغى الكتف.\n• ثبّت لوحي الكتف للخلف وانزل بتحكم.\n• لا ترفع الأرداف عن المقعد.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Sternal Cable Press Around","notes":"ملاحظات مهمة:\n• لا تغلق المرفقين بقوة في أعلى الحركة، وركّز على تقريب الذراعين نحو منتصف الصدر.\n• حافظ على كتفين ثابتين وللخلف.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Machine Chest Fly","notes":"ملاحظات مهمة:\n• مرفقان بثني خفيف ثابت طوال الحركة، والحركة من مفصل الكتف.\n• افتح حتى إحساس بتمدد مريح في الصدر ولا تتجاوزه.\n• اعصر الصدر في الأعلى لثانية.\n• اضبط المقعد والمساند لتتماشى مفاصلك مع محور الجهاز قبل البدء، وسجّل الإعدادات لتكررها.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Bar Cable Chest Press","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Cable Chest Fly","notes":"ملاحظات مهمة:\n• مرفقان بثني خفيف ثابت طوال الحركة، والحركة من مفصل الكتف.\n• افتح حتى إحساس بتمدد مريح في الصدر ولا تتجاوزه.\n• اعصر الصدر في الأعلى لثانية.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Bent Knee Push-up","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Stability Ball Push-Up","notes":"ملاحظات مهمة:\n• ثبّت لوحي الكتف للخلف وللأسفل وأبقِ الصدر مرفوعاً طوال التمرين.\n• انزل بتحكم حتى مستوى الصدر، والمرفقان بزاوية نحو 45–70° من الجسم لا مفتوحين تماماً.\n• ادفع بخط ثابت دون رفع الكتفين نحو الأذن.\n• ثبّت الكرة جيداً قبل البدء، وتحرك ببطء لتجنب الانزلاق.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Cable Reardelt Rows","notes":"ملاحظات مهمة:\n• المرفقان بزاوية أوسع، اسحب نحو أعلى الصدر مع ضم لوحي الكتف.\n• حافظ على ظهر محايد دون تدوير الكتفين للأمام.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"DB Chest Supported Reardelt Row","notes":"ملاحظات مهمة:\n• المرفقان بزاوية أوسع، اسحب نحو أعلى الصدر مع ضم لوحي الكتف.\n• حافظ على ظهر محايد دون تدوير الكتفين للأمام.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Bent-over Barbell Row","notes":"ملاحظات مهمة:\n• ابدأ الحركة بسحب لوحي الكتف نحو بعضهما ثم اسحب بالمرفقين.\n• اجعل الصدر ثابتاً ولا تتمايل بالجذع لإكمال التكرار.\n• اضغط في نهاية الحركة لثانية وارجع ببطء.\n• ثبّت قبضة البار وارفع بتحكم، واستعن بمساعد أو حوامل أمان عند الأوزان الثقيلة.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Cable Reardelt Fly","notes":"ملاحظات مهمة:\n• مرفقان مثنيان قليلاً وافتح للجانبين مع تركيز على الكتف الخلفي.\n• حافظ على الظهر محايداً ولا تستخدم الزخم.\n• وزن خفيف مع انقباض لثانية في الأعلى.\n• اضبط الارتفاع بما يناسب الحركة، وحافظ على شدّ الكيبل طوال التمرين دون ترك الوزن يرتطم.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"DB Chest Supported Row","notes":"ملاحظات مهمة:\n• ابدأ الحركة بسحب لوحي الكتف نحو بعضهما ثم اسحب بالمرفقين.\n• اجعل الصدر ثابتاً ولا تتمايل بالجذع لإكمال التكرار.\n• اضغط في نهاية الحركة لثانية وارجع ببطء.\n• اختر وزناً تتحكم به في كل تكرار دون تأرجح، وأنزل الدمبلين بنفس السرعة التي رفعتهما.\n• اترك عدد التكرارات الاحتياطية التي كتبتها المدربة (RIR)، ولا تضحِّ بالتقنية لأجل الوزن. توقف عند ألم حاد أو غير معتاد، وراجع المدربة."},{"name":"Head Supported Row","notes":"ملاحظات مهمة:\n• ابدأ الحركة بسحب لوحي الكتف نحو بعضهما ثم اسحب بالمرفقين.\n• اجعل الصدر ثابتاً ولا تتمايل بالجذع لإكمال التكرار.\n• اضغط في نهاية الحركة لثانية وارجع ببطء.\n• اترك ع